/**
 * Ownership-handover offers. Every read and write is filtered by `orgId`.
 *
 * A row stays `pending` until someone resolves it; whether a pending row has
 * lapsed is a question of `expiresAt` against the caller's clock, answered by
 * the service. The only writes that look at the clock are the ones that need
 * it to stay correct: `insertHandover` retires lapsed rows so they cannot
 * block a new offer, and the resolving writes refuse a lapsed row.
 */
import { and, eq, gt, isNull, lte, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, members, organizations, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toOrganization, toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, MemberId, OrgId, UserId } from "@/types/common";
import type { Role } from "@/types/member";
import type { Organization, OwnershipHandover } from "@/types/organization";

/** A role the handover moved a member to, for the caller to announce. */
export interface HandoverRoleChange {
  readonly memberId: MemberId;
  readonly userId: UserId;
  readonly from: Role;
  readonly to: Role;
}

export interface HandoverTransfer {
  readonly organization: Organization;
  readonly roleChanges: readonly HandoverRoleChange[];
}

/** The offer still marked `pending` for the org, lapsed or not. */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/**
 * Writes a new offer, or returns `null` when one is still open. Offers that
 * lapsed before `createdAt` are retired first, in the same transaction, so a
 * stale row never blocks a fresh one.
 */
export async function insertHandover(input: {
  readonly orgId: OrgId;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly createdAt: IsoTimestamp;
  readonly expiresAt: IsoTimestamp;
}): Promise<OwnershipHandover | null> {
  return getDb().transaction((tx) => {
    tx.update(ownershipHandovers)
      .set({ status: "expired", resolvedAt: ownershipHandovers.expiresAt })
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, input.orgId),
          eq(ownershipHandovers.status, "pending"),
          lte(ownershipHandovers.expiresAt, input.createdAt),
        ),
      )
      .run();

    const open = tx
      .select({ id: ownershipHandovers.id })
      .from(ownershipHandovers)
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, input.orgId),
          eq(ownershipHandovers.status, "pending"),
        ),
      )
      .get();
    if (open) return null;

    const row = tx
      .insert(ownershipHandovers)
      .values({
        id: newId(),
        orgId: input.orgId,
        fromUserId: input.fromUserId,
        toUserId: input.toUserId,
        status: "pending",
        expiresAt: input.expiresAt,
        createdAt: input.createdAt,
        resolvedAt: null,
      })
      .returning()
      .get();

    return toOwnershipHandover(row);
  });
}

/**
 * Closes an open offer as declined or withdrawn. `null` when the offer is no
 * longer pending or has lapsed by `at`; nothing is written in that case.
 */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: "declined" | "canceled",
  at: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
      ),
    )
    .returning()
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/** Withdraws the open offer that involves `userId` on either side, if any. */
export async function cancelOpenHandoversForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
