 * Accepts the offer and moves ownership in one transaction: the recipient is
 * promoted to owner first, the recorded owner is switched, and only then does
 * the previous owner step down to admin — so the organization holds an owner
 * at every instant and the last-owner rule is never in play. The previous
 * owner is only touched if they still hold the owner role, and the recipient
 * only if they do not.
 *
 * Returns `null` without writing anything when the offer is no longer open or
 * the recipient is no longer an active member.
 */
export async function transferOwnership(input: {
  readonly orgId: OrgId;
  readonly handoverId: string;
  readonly fromUserId: UserId;
  readonly toUserId: UserId;
  readonly at: IsoTimestamp;
}): Promise<HandoverTransfer | null> {
  const { orgId, at } = input;

  return getDb().transaction((tx) => {
    const liveMember = (userId: UserId) =>
      tx
        .select()
        .from(members)
        .where(
          and(
            orgPredicate(members.orgId, orgId),
            eq(members.userId, userId),
            isNull(members.archivedAt),
          ),
        )
        .get();

    const incoming = liveMember(input.toUserId);
    if (!incoming || incoming.status !== "active") return null;

    const accepted = tx
      .update(ownershipHandovers)
      .set({ status: "accepted", resolvedAt: at })
      .where(
        and(
          orgPredicate(ownershipHandovers.orgId, orgId),
          eq(ownershipHandovers.id, input.handoverId),
          eq(ownershipHandovers.status, "pending"),
          gt(ownershipHandovers.expiresAt, at),
        ),
      )
      .returning({ id: ownershipHandovers.id })
      .get();
    if (!accepted) return null;

    const outgoing = liveMember(input.fromUserId);
    const setRole = (memberId: string, role: Role) =>
      tx
        .update(members)
        .set({ role, updatedAt: at })
        .where(and(orgPredicate(members.orgId, orgId), eq(members.id, memberId)))
        .run();

    const roleChanges: HandoverRoleChange[] = [];

    if (incoming.role !== "owner") {
      setRole(incoming.id, "owner");
      roleChanges.push({
        memberId: incoming.id as MemberId,
        userId: input.toUserId,
        from: incoming.role,
        to: "owner",
      });
    }

    const organization = tx
      .update(organizations)
      .set({ ownerId: input.toUserId, updatedAt: at })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    if (outgoing && outgoing.role === "owner") {
      setRole(outgoing.id, "admin");
      roleChanges.push({
        memberId: outgoing.id as MemberId,
        userId: input.fromUserId,
        from: "owner",
        to: "admin",
      });
    }

    return { organization: toOrganization(organization), roleChanges };
  });
}

