/**
 * Ownership handover: offer, accept, decline, withdraw and lapse.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError, isDomainError, toAppError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import * as orgService from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { emit } from "@/lib/event-bus";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;

let cleanup: () => void;
let detachAudit: Unsubscribe;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function refuses(promise: Promise<unknown>, reason: string): Promise<void> {
  const error = await promise.then(
    () => null,
    (caught: unknown) => caught,
  );
  expect(error).toBeInstanceOf(OwnershipHandoverError);
  expect((error as OwnershipHandoverError).reason).toBe(reason);
}

async function notificationsFor(orgId: OrgId, userId: UserId) {
  const page = await notificationRepo.listNotifications({
    orgId,
    recipientId: userId,
    unreadOnly: false,
    limit: 50,
    cursor: null,
  });
  return page.items;
}

async function roleOf(tenant: Tenant, role: Role): Promise<Role | undefined> {
  return (await memberRepo.findMember(tenant.org.id, tenant.userIds[role]))?.role;
}

async function makeSecondOwner(tenant: Tenant): Promise<Actor> {
  const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
  if (!admin) throw new Error("fixture admin missing");
  await memberRepo.updateMemberRole(tenant.org.id, admin.id, "owner");
  return { ...tenant.actors.admin, role: "owner" };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachAudit = registerActivityListeners();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  detachAudit();
  cleanup();
});

describe("offering", () => {
  it("records a seven-day offer, visible to every member, and alerts only the offered member", async () => {
    const tenant = await createTenant("handover-offer");
    const { orgId } = { orgId: tenant.org.id };

    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );

    expect(offer).toMatchObject({
      orgId,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.member,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(offer.expiresAt) - Date.parse(offer.createdAt)).toBe(7 * DAY_MS);

    for (const role of ["owner", "admin", "member", "viewer"] as const) {
      await expect(
        orgService.getPendingOwnershipHandover(tenant.actors[role], orgId),
      ).resolves.toEqual(offer);
    }

    const alerts = await notificationsFor(orgId, tenant.userIds.member);
    expect(alerts.filter((n) => n.kind === "ownership_handover")).toHaveLength(1);
    for (const role of ["owner", "admin", "viewer"] as const) {
      const others = await notificationsFor(orgId, tenant.userIds[role]);
      expect(others.filter((n) => n.kind === "ownership_handover")).toHaveLength(0);
    }
  });

  it("reports no offer when none is open", async () => {
    const tenant = await createTenant("handover-none");
    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.viewer, tenant.org.id),
    ).resolves.toBeNull();
  });

  it("refuses a second offer while one is open, until it is withdrawn or declined", async () => {
    const tenant = await createTenant("handover-single");
    const { owner, member, admin } = tenant.actors;
    const orgId = tenant.org.id;

    await orgService.initiateOwnershipHandover(owner, orgId, tenant.userIds.member);
    await refuses(
      orgService.initiateOwnershipHandover(owner, orgId, tenant.userIds.admin),
      "pending_exists",
    );

    const withdrawn = await orgService.cancelOwnershipHandover(owner, orgId);
    expect(withdrawn.status).toBe("canceled");
    expect(withdrawn.resolvedAt).not.toBeNull();

    await orgService.initiateOwnershipHandover(owner, orgId, tenant.userIds.admin);
    const declined = await orgService.declineOwnershipHandover(admin, orgId);
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).not.toBeNull();
    await expect(orgService.getPendingOwnershipHandover(member, orgId)).resolves.toBeNull();

    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, tenant.userIds.viewer),
    ).resolves.toMatchObject({ status: "pending", toUserId: tenant.userIds.viewer });
  });

  it("is reserved to the recorded owner, not to whoever holds the owner role", async () => {
    const tenant = await createTenant("handover-recorded");
    const orgId = tenant.org.id;
    const secondOwner = await makeSecondOwner(tenant);

    for (const actor of [secondOwner, tenant.actors.member, tenant.actors.viewer]) {
      await expect(
        orgService.initiateOwnershipHandover(actor, orgId, tenant.userIds.viewer),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );
    await expect(orgService.cancelOwnershipHandover(secondOwner, orgId)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(
      orgService.cancelOwnershipHandover(tenant.actors.member, orgId),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses the owner as target and unknown, foreign or removed users", async () => {
    const tenant = await createTenant("handover-targets");
    const other = await createTenant("handover-targets-other");
    const orgId = tenant.org.id;
    const { owner } = tenant.actors;

    await refuses(
      orgService.initiateOwnershipHandover(owner, orgId, tenant.userIds.owner),
      "self",
    );
    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, "01HZZZZZZZZZZZZZZZZZZZZZZZ" as UserId),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, other.userIds.member),
    ).rejects.toBeInstanceOf(NotFoundError);

    const viewer = await memberRepo.findMember(orgId, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture viewer missing");
    await memberService.removeMember(owner, { orgId, memberId: viewer.id });
    await expect(
      orgService.initiateOwnershipHandover(owner, orgId, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("accepting", () => {
  it("moves ownership, roles and everything that follows the owner", async () => {
    const tenant = await createTenant("handover-accept");
    const orgId = tenant.org.id;
    const roleEvents = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.viewer,
    );

    const organization = await orgService.acceptOwnershipHandover(tenant.actors.viewer, orgId);

    expect(organization.ownerId).toBe(tenant.userIds.viewer);
    expect((await orgRepo.findOrgById(orgId))?.ownerId).toBe(tenant.userIds.viewer);
    expect(await roleOf(tenant, "viewer")).toBe("owner");
    expect(await roleOf(tenant, "owner")).toBe("admin");
    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.member, orgId),
    ).resolves.toBeNull();

    const viewerMember = await memberRepo.findMember(orgId, tenant.userIds.viewer);
    const ownerMember = await memberRepo.findMember(orgId, tenant.userIds.owner);
    expect(roleEvents).toHaveLength(2);
    expect(roleEvents).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          orgId,
          actorId: tenant.userIds.viewer,
          memberId: viewerMember?.id,
          from: "viewer",
          to: "owner",
        }),
        expect.objectContaining({
          orgId,
          actorId: tenant.userIds.viewer,
          memberId: ownerMember?.id,
          from: "owner",
          to: "admin",
        }),
      ]),
    );
    expect(transfers).toHaveLength(1);
    expect(transfers[0]).toMatchObject({
      orgId,
      actorId: tenant.userIds.viewer,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.viewer,
    });

    const audit = await activityRepo.listActivity({
      orgId,
      action: ["organization.ownership_transferred"],
      limit: 10,
      cursor: null,
    });
    expect(audit.items).toHaveLength(1);
    expect(audit.items[0]).toMatchObject({
      action: "organization.ownership_transferred",
      actorId: tenant.userIds.viewer,
      subjectKind: "organization",
      subjectId: orgId,
      metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.viewer },
    });
  });

  it("hands alerts, billing and removability over to the new owner", async () => {
    const tenant = await createTenant("handover-follow");
    const orgId = tenant.org.id;

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );
    await orgService.acceptOwnershipHandover(tenant.actors.member, orgId);

    const joiner = "01HZZZZZZZZZZZZZZZZZZZZZZY" as UserId;
    await emit("member.joined", {
      orgId,
      actorId: joiner,
      occurredAt: tenant.org.createdAt,
      memberId: "01HZZZZZZZZZZZZZZZZZZZZZZX" as never,
      userId: joiner,
      role: "member",
    });
    const forNew = await notificationsFor(orgId, tenant.userIds.member);
    const forOld = await notificationsFor(orgId, tenant.userIds.owner);
    expect(forNew.filter((n) => n.kind === "member_joined")).toHaveLength(1);
    expect(forOld.filter((n) => n.kind === "member_joined")).toHaveLength(0);

    const newOwner: Actor = { ...tenant.actors.member, role: "owner" };
    const previous: Actor = { ...tenant.actors.owner, role: "admin" };
    await expect(
      billingService.changePlan(previous, { orgId, plan: "starter", interval: "monthly" }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      billingService.changePlan(newOwner, { orgId, plan: "starter", interval: "monthly" }),
    ).resolves.toMatchObject({ plan: "starter" });

    const previousMember = await memberRepo.findMember(orgId, tenant.userIds.owner);
    if (!previousMember) throw new Error("previous owner missing");
    await expect(
      memberService.removeMember(newOwner, { orgId, memberId: previousMember.id }),
    ).resolves.toMatchObject({ userId: tenant.userIds.owner });
  });

  it("only demotes the previous owner when the recipient already owns", async () => {
    const tenant = await createTenant("handover-two-owners");
    const orgId = tenant.org.id;
    const secondOwner = await makeSecondOwner(tenant);
    const roleEvents = capture("member.role_changed");

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.admin,
    );
    await orgService.acceptOwnershipHandover(secondOwner, orgId);

    expect(await roleOf(tenant, "admin")).toBe("owner");
    expect(await roleOf(tenant, "owner")).toBe("admin");
    expect(roleEvents).toHaveLength(1);
    expect(roleEvents[0]).toMatchObject({ from: "owner", to: "admin" });
  });

  it("leaves a previous owner who no longer holds the owner role as they are", async () => {
    const tenant = await createTenant("handover-demoted");
    const orgId = tenant.org.id;
    const secondOwner = await makeSecondOwner(tenant);
    const ownerMember = await memberRepo.findMember(orgId, tenant.userIds.owner);
    if (!ownerMember) throw new Error("owner missing");

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.viewer,
    );
    await memberRepo.updateMemberRole(orgId, ownerMember.id, "member");
    const roleEvents = capture("member.role_changed");

    await orgService.acceptOwnershipHandover(tenant.actors.viewer, orgId);

    expect(await roleOf(tenant, "owner")).toBe("member");
    expect(await roleOf(tenant, "viewer")).toBe("owner");
    expect(roleEvents).toHaveLength(1);
    expect(roleEvents[0]).toMatchObject({ from: "viewer", to: "owner" });
    void secondOwner;
  });

  it("can only be done once, and only by the offered member", async () => {
    const tenant = await createTenant("handover-accept-guard");
    const orgId = tenant.org.id;

    await refuses(
      orgService.acceptOwnershipHandover(tenant.actors.member, orgId),
      "nothing_pending",
    );

    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );
    for (const actor of [tenant.actors.owner, tenant.actors.admin, tenant.actors.viewer]) {
      await refuses(orgService.acceptOwnershipHandover(actor, orgId), "nothing_pending");
      await refuses(orgService.declineOwnershipHandover(actor, orgId), "nothing_pending");
    }

    await orgService.acceptOwnershipHandover(tenant.actors.member, orgId);
    await refuses(
      orgService.acceptOwnershipHandover(tenant.actors.member, orgId),
      "nothing_pending",
    );
    await refuses(
      orgService.cancelOwnershipHandover({ ...tenant.actors.member, role: "owner" }, orgId),
      "nothing_pending",
    );
  });

  it("cannot be declined or withdrawn after a withdrawal", async () => {
    const tenant = await createTenant("handover-after-cancel");
    const orgId = tenant.org.id;

    await refuses(orgService.cancelOwnershipHandover(tenant.actors.owner, orgId), "nothing_pending");
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );
    await orgService.cancelOwnershipHandover(tenant.actors.owner, orgId);
    await refuses(orgService.declineOwnershipHandover(tenant.actors.member, orgId), "nothing_pending");
    await refuses(orgService.acceptOwnershipHandover(tenant.actors.member, orgId), "nothing_pending");
    expect((await orgRepo.findOrgById(orgId))?.ownerId).toBe(tenant.userIds.owner);
  });
});

describe("lapsing", () => {
  it("is actionable before seven days and not from seven days on", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    const start = new Date("2030-01-01T00:00:00.000Z");
    vi.setSystemTime(start);

    const tenant = await createTenant("handover-lapse");
    const orgId = tenant.org.id;
    const offer = await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );
    expect(offer.expiresAt).toBe("2030-01-08T00:00:00.000Z");

    vi.setSystemTime(new Date(start.getTime() + 7 * DAY_MS - 1));
    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.viewer, orgId),
    ).resolves.toMatchObject({ id: offer.id });

    vi.setSystemTime(new Date(start.getTime() + 7 * DAY_MS));
    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.viewer, orgId),
    ).resolves.toBeNull();
    await refuses(orgService.acceptOwnershipHandover(tenant.actors.member, orgId), "expired");
    await refuses(orgService.declineOwnershipHandover(tenant.actors.member, orgId), "expired");
    await refuses(orgService.acceptOwnershipHandover(tenant.actors.viewer, orgId), "nothing_pending");
    await refuses(orgService.cancelOwnershipHandover(tenant.actors.owner, orgId), "nothing_pending");

    // Acting on a lapsed offer changed nothing.
    expect((await orgRepo.findOrgById(orgId))?.ownerId).toBe(tenant.userIds.owner);
    expect(await roleOf(tenant, "member")).toBe("member");
    expect(await roleOf(tenant, "owner")).toBe("owner");

    // ...and it no longer blocks a new offer.
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin),
    ).resolves.toMatchObject({ status: "pending", toUserId: tenant.userIds.admin });
  });

  it("still accepts one instant before expiry", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    const start = new Date("2031-06-01T12:00:00.000Z");
    vi.setSystemTime(start);

    const tenant = await createTenant("handover-last-instant");
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    vi.setSystemTime(new Date(start.getTime() + 7 * DAY_MS - 1));
    const organization = await orgService.acceptOwnershipHandover(
      tenant.actors.member,
      tenant.org.id,
    );
    expect(organization.ownerId).toBe(tenant.userIds.member);
  });
});

describe("leaving", () => {
  it("withdraws the offer when the offered member is removed", async () => {
    const tenant = await createTenant("handover-recipient-leaves");
    const orgId = tenant.org.id;
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );

    const member = await memberRepo.findMember(orgId, tenant.userIds.member);
    if (!member) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, { orgId, memberId: member.id });

    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.viewer, orgId),
    ).resolves.toBeNull();
    await expect(
      orgService.initiateOwnershipHandover(tenant.actors.owner, orgId, tenant.userIds.admin),
    ).resolves.toMatchObject({ status: "pending" });
  });

  it("withdraws the offer when the offering owner is removed", async () => {
    const tenant = await createTenant("handover-owner-leaves");
    const orgId = tenant.org.id;
    const secondOwner = await makeSecondOwner(tenant);
    await orgService.initiateOwnershipHandover(
      tenant.actors.owner,
      orgId,
      tenant.userIds.member,
    );

    const ownerMember = await memberRepo.findMember(orgId, tenant.userIds.owner);
    if (!ownerMember) throw new Error("owner missing");
    await memberService.removeMember(secondOwner, { orgId, memberId: ownerMember.id });

    await expect(
      orgService.getPendingOwnershipHandover(tenant.actors.viewer, orgId),
    ).resolves.toBeNull();
    await refuses(
      orgService.acceptOwnershipHandover(tenant.actors.member, orgId),
      "nothing_pending",
    );
  });
});

describe("tenancy and errors", () => {
  it("rejects an orgId outside the actor's workspace on every operation", async () => {
    const tenant = await createTenant("handover-scope-a");
    const other = await createTenant("handover-scope-b");
    await orgService.initiateOwnershipHandover(
      other.actors.owner,
      other.org.id,
      other.userIds.member,
    );

    const foreign = other.org.id;
    const { owner, member } = tenant.actors;
    await expect(
      orgService.initiateOwnershipHandover(owner, foreign, tenant.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(orgService.acceptOwnershipHandover(member, foreign)).rejects.toBeInstanceOf(
      TenantScopeError,
    );
    await expect(orgService.declineOwnershipHandover(member, foreign)).rejects.toBeInstanceOf(
      TenantScopeError,
    );
    await expect(orgService.cancelOwnershipHandover(owner, foreign)).rejects.toBeInstanceOf(
      TenantScopeError,
    );
    await expect(orgService.getPendingOwnershipHandover(member, foreign)).rejects.toBeInstanceOf(
      TenantScopeError,
    );

    // The other workspace's offer is invisible from here.
    await expect(
      orgService.getPendingOwnershipHandover(member, tenant.org.id),
    ).resolves.toBeNull();
    await refuses(orgService.acceptOwnershipHandover(member, tenant.org.id), "nothing_pending");
  });

  it("maps the refusal to the conflict code", () => {
    const error = new OwnershipHandoverError("expired");
    expect(error).toBeInstanceOf(Error);
    expect(error.code).toBe("conflict");
    expect(error.reason).toBe("expired");
    expect(isDomainError(error)).toBe(true);
    expect(toAppError(error)).toMatchObject({ code: "conflict", meta: { reason: "expired" } });
  });
});

